#ifndef ORDER_HPP
#define ORDER_HPP

#include "../common/TimeUtils.hpp"
#include "../common/Types.hpp"

namespace trading {

/*
 * Represents an order generated by the strategy and
 * passed through the risk and execution pipeline.
 */
struct Order {
    OrderId order_id;
    InstrumentId instrument_id;

    Side side;
    OrderType type;

    PriceTick price;
    Quantity quantity;

    Quantity filled_quantity;

    OrderStatus status;

    /*
     * Local timestamp when the strategy created
     * the order.
     */
    TimePoint created_at;
};

/*
 * Result returned by the exchange simulator after
 * attempting to execute an order.
 */
struct ExecutionReport {
    OrderId order_id;
    InstrumentId instrument_id;

    Side side;

    PriceTick execution_price;
    Quantity execution_quantity;

    OrderStatus status;

    /*
     * Local timestamp when execution was simulated.
     */
    TimePoint timestamp;
};

} // namespace trading

#endif